@article{Stańczak_Torroba Hennigen_Williams_Cotterell_Augenstein_2023, title={A Latent-Variable Model for Intrinsic Probing}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26593}, DOI={10.1609/aaai.v37i11.26593}, abstractNote={The success of pre-trained contextualized representations has prompted researchers to analyze them for the presence of linguistic information. Indeed, it is natural to assume that these pre-trained representations do encode some level of linguistic knowledge as they have brought about large empirical improvements on a wide variety of NLP tasks, which suggests they are learning true linguistic generalization.
In this work, we focus on intrinsic probing, an analysis technique where the goal is not only to identify whether a representation encodes a linguistic attribute but also to pinpoint where this attribute is encoded.
We propose a novel latent-variable formulation for constructing intrinsic probes and derive a tractable variational approximation to the log-likelihood.
Our results show that our model is versatile and yields tighter mutual information estimates than two intrinsic probes previously proposed in the literature.
Finally, we find empirical evidence that pre-trained representations develop a cross-lingually entangled notion of morphosyntax.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Stańczak, Karolina and Torroba Hennigen, Lucas and Williams, Adina and Cotterell, Ryan and Augenstein, Isabelle}, year={2023}, month={Jun.}, pages={13591-13599} }

@article{Huang_Hsueh_Chien_Wang_Wang_Peng_2024, title={A Reinforcement Learning Badminton Environment for Simulating Player Tactics (Student Abstract)}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26976}, DOI={10.1609/aaai.v37i13.26976}, abstractNote={Recent techniques for analyzing sports precisely has stimulated various approaches to improve player performance and fan engagement.
However, existing approaches are only able to evaluate offline performance since testing in real-time matches requires exhaustive costs and cannot be replicated.
To test in a safe and reproducible simulator, we focus on turn-based sports and introduce a badminton environment by simulating rallies with different angles of view and designing the states, actions, and training procedures.
This benefits not only coaches and players by simulating past matches for tactic investigation, but also researchers from rapidly evaluating their novel algorithms.
Our code is available at https://github.com/wywyWang/CoachAI-Projects/tree/main/Strategic%20Environment.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Li-Chun and Hsueh, Nai-Zen and Chien, Yen-Che and Wang, Wei-Yao and Wang, Kuang-Da and Peng, Wen-Chih}, year={2024}, month={Jul.}, pages={16232-16233} }

@article{Alfano_Greco_Parisi_Trubitsyna_2023, title={Abstract Argumentation Framework with Conditional Preferences}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25766}, DOI={10.1609/aaai.v37i5.25766}, abstractNote={Dung’s abstract Argumentation Framework (AF) has emerged as a central formalism in the area of knowledge representation and reasoning.
Preferences in AF allow to represent the comparative strength of arguments in a simple yet expressive way. Preference-based AF (PAF) has been proposed to extend AF with preferences of the form a &gt; b, whose intuitive meaning is that argument a is better than b. In this paper we generalize PAF by introducing conditional preferences of the form a &gt; b \leftarrow body that informally state that a is better than b whenever the condition expressed by body is true.
The resulting framework, namely Conditional Preference-based AF (CPAF), extends the PAF semantics under three well-known preference criteria, i.e. democratic, elitist, and KTV. After introducing CPAF, we study the complexity of the verification problem (deciding whether a set of arguments is a ``best’’ extension) as well as of the credulous and skeptical acceptance problems (deciding whether a given argument belongs to any or all ``best’’ extensions, respectively) under multiple-status semantics (that is, complete, preferred, stable, and semi-stable semantics) for the above-mentioned preference criteria.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Alfano, Gianvincenzo and Greco, Sergio and Parisi, Francesco and Trubitsyna, Irina}, year={2023}, month={Jun.}, pages={6218-6227} }

@article{Guibon_Labeau_Lefeuvre_Clavel_2023, title={An Adaptive Layer to Leverage Both Domain and Task Specific Information from Scarce Data}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25940}, DOI={10.1609/aaai.v37i6.25940}, abstractNote={Many companies make use of customer service chats to help the customer and try to solve their problem. However, customer service data is confidential and as such, cannot easily be shared in the research community. This also implies that these
data are rarely labeled, making it difficult to take advantage of it with machine learning methods. In this paper we present the first work on a customer’s problem status prediction and identification of problematic conversations. Given very small
subsets of labeled textual conversations and unlabeled ones, we propose a semi-supervised framework dedicated to customer service data leveraging speaker role information to adapt the model to the domain and the task using a two-step process. Our framework, Task-Adaptive Fine-tuning, goes from predicting customer satisfaction to identifying the status of the customer’s problem, with the latter being the main objective of the multi-task setting. It outperforms recent inductive semi-supervised approaches on this novel task while only considering a relatively low number of parameters to train on during the final target task. We believe it can not only serve models dedicated to customer service but also to any other application making use of confidential conversational data where labeled sets are rare. Source code is available at https://github.com/gguibon/taft}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Guibon, Gaël and Labeau, Matthieu and Lefeuvre, Luce and Clavel, Chloé}, year={2023}, month={Jun.}, pages={7757-7765} }

@article{Keren_2024, title={Better Environments for Better AI}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26809}, DOI={10.1609/aaai.v37i13.26809}, abstractNote={Most past research aimed at increasing the capabilities of AI methods has focused exclusively on the AI agent itself, i.e., given some input, what are the improvements to the agent’s reasoning that will yield the best possible output. In my research, I take a novel approach to increasing the capabilities of AI agents via the design of the environments in which they are intended to act. My methods for automated design identify the inherent capabilities and limitations of AI agents with respect to their environment and find the best way to modify the environment to account for those limitations and maximize the agents’ performance. The future will bring an ever increasing set of interactions between people and automated agents, whether at home, at the workplace, on the road, or across many other everyday settings. Autonomous vehicles, robotic tools, medical devices, and smart
homes, all allow ample opportunity for human-robot and multi-agent interactions. In these settings, recognizing what agents are trying to achieve, providing relevant assistance, and supporting an effective collaboration are essential tasks, and tasks
that can all be enhanced via careful environment design. However, the increasing complexity of the systems we use and the environments in which we operate makes devising good design solutions extremely challenging. This stresses the importance
of developing automated design tools to help determine the most effective ways to apply change and enable robust AI systems. My long-term goal is to provide theoretical foundations for designing AI systems that are capable of effective partnership in sustainable and efficient collaborations of automated agents as well as of automated agents and people.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Keren, Sarah}, year={2024}, month={Jul.}, pages={15442-15442} }

@article{Yang_Spaan_2023, title={CEM: Constrained Entropy Maximization for Task-Agnostic Safe Exploration}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26281}, DOI={10.1609/aaai.v37i9.26281}, abstractNote={In the absence of assigned tasks, a learning agent typically seeks to explore its environment efficiently. However, the pursuit of exploration will bring more safety risks.
An under-explored aspect of reinforcement learning is how to achieve safe efficient exploration when the task is unknown.
In this paper, we propose a practical Constrained Entropy Maximization (CEM) algorithm to solve task-agnostic safe exploration problems, which naturally require a finite horizon and undiscounted constraints on safety costs.
The CEM algorithm aims to learn a policy that maximizes state entropy under the premise of safety.
To avoid approximating the state density in complex domains, CEM leverages a k-nearest neighbor entropy estimator to evaluate the efficiency of exploration.
In terms of safety, CEM minimizes the safety costs, and adaptively trades off safety and exploration based on the current constraint satisfaction. The empirical analysis shows that CEM enables the acquisition of a safe exploration policy in complex environments, resulting in improved performance in both safety and sample efficiency for target tasks.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yang, Qisong and Spaan, Matthijs T.J.}, year={2023}, month={Jun.}, pages={10798-10806} }

@article{Reichl_Slivovsky_Szeider_2023, title={Circuit Minimization with QBF-Based Exact Synthesis}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25524}, DOI={10.1609/aaai.v37i4.25524}, abstractNote={This paper presents a rewriting method for Boolean circuits that minimizes small subcircuits with exact synthesis. Individual synthesis tasks are encoded as Quantified Boolean Formulas (QBFs) that capture the full flexibility for implementing multi-output subcircuits.
This is in contrast to SAT-based resynthesis, where &quot;don’t cares&quot; are computed for an individual gate, and replacements are confined to the circuitry used exclusively by that gate.
An implementation of our method achieved substantial size reductions compared to state-of-the-art methods across a wide range of benchmark circuits.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Reichl, Franz-Xaver and Slivovsky, Friedrich and Szeider, Stefan}, year={2023}, month={Jun.}, pages={4087-4094} }

@article{Rajani_Arndt_Blanco-Mulero_Luck_Kyrki_2023, title={Co-imitation: Learning Design and Behaviour by Imitation}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25764}, DOI={10.1609/aaai.v37i5.25764}, abstractNote={The co-adaptation of robots has been a long-standing research endeavour with the goal of adapting both body and behaviour of a robot for a given task, inspired by the natural evolution of animals. Co-adaptation has the potential to eliminate costly manual hardware engineering as well as improve the performance of systems.
The standard approach to co-adaptation is to use a reward function for optimizing behaviour and morphology. However, defining and constructing such reward functions is notoriously difficult and often a significant engineering effort.
This paper introduces a new viewpoint on the co-adaptation problem, which we call co-imitation: finding a morphology and a policy that allow an imitator to closely match the behaviour of a demonstrator. To this end we propose a co-imitation methodology for adapting behaviour and morphology by matching state-distributions of the demonstrator. Specifically, we focus on the challenging scenario with mismatched state- and action-spaces between both agents. We find that co-imitation increases behaviour similarity across a variety of tasks and settings, and demonstrate co-imitation by transferring human walking, jogging and kicking skills onto a simulated humanoid.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Rajani, Chang and Arndt, Karol and Blanco-Mulero, David and Luck, Kevin Sebastian and Kyrki, Ville}, year={2023}, month={Jun.}, pages={6200-6208} }

@article{Hui_Fang_Xia_Aykent_Ku_2023, title={Constrained Market Share Maximization by Signal-Guided Optimization}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25552}, DOI={10.1609/aaai.v37i4.25552}, abstractNote={With the rapid development of the airline
industry, maximizing the market share with a
constrained budget is an urgent econometric problem for an airline. We investigate the problem by adjusting flight frequencies on different flight routes. Owing to the large search space of solutions and the difficulty of predicting the market, this problem is in general daunting to solve. This paper proposes a novel two-stage optimization method to address the challenges. On the higher level, we use a signal to guide the optimization process toward a constrained satisfying solution. On the lower level, we consider the consecutive itineraries in real scenarios and model the unseen correlations between routes in itineraries for market share prediction. In theory, we prove the convergence of our optimization approach. In the experiment, we empirically verify the superiority of both our prediction model and optimization approach over existing works with large-scale real-world data. Our code has been released at: https://github.com/codingAndBS/AirlineMarket.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Hui, Bo and Fang, Yuchen and Xia, Tian and Aykent, Sarp and Ku, Wei-Shinn}, year={2023}, month={Jun.}, pages={4330-4338} }

@article{Vogler_Goyal_Reddy_Pertseva_Lemley_Warren_G’Sell_Berg-Kirkpatrick_2023, title={Contrastive Attention Networks for Attribution of Early Modern Print}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25659}, DOI={10.1609/aaai.v37i4.25659}, abstractNote={In this paper, we develop machine learning techniques to identify unknown printers in early modern (c.~1500--1800) English printed books.
Specifically, we focus on matching uniquely damaged character type-imprints in anonymously printed books to works with known printers in order to provide evidence of their origins.
Until now, this work has been limited to manual investigations by analytical bibliographers.
We present a Contrastive Attention-based Metric Learning approach to identify similar damage across character image pairs, which is sensitive to very subtle differences in glyph shapes, yet robust to various confounding sources of noise associated with digitized historical books. To overcome the scarce amount of supervised data, we design a random data synthesis procedure that aims to simulate bends, fractures, and inking variations induced by the early printing process.
Our method successfully improves downstream damaged type-imprint matching among printed works from this period, as validated by in-domain human experts. The results of our approach on two important philosophical works from the Early Modern period demonstrate potential to extend the extant historical research about the origins and content of these books.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Vogler, Nikolai and Goyal, Kartik and Reddy, Kishore PV and Pertseva, Elizaveta and Lemley, Samuel V. and Warren, Christopher N. and G’Sell, Max and Berg-Kirkpatrick, Taylor}, year={2023}, month={Jun.}, pages={5285-5293} }

@article{Du_2024, title={Cooperative Multi-Agent Learning in a Complex World: Challenges and Solutions}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26803}, DOI={10.1609/aaai.v37i13.26803}, abstractNote={Over the past few years, artificial intelligence (AI) has achieved great success in a variety of applications, such as image classification and recommendation systems. This success has often been achieved by training machine learning models on static datasets, where inputs and desired outputs are provided.
However, we are now seeing a shift in this paradigm. Instead of learning from static datasets, machine learning models are increasingly being trained through feedback from their interactions with the world. This is particularly important when machine learning models are deployed in the real world, as their decisions can often have an impact on other agents, turning the decision-making process into a multi-agent problem.
As a result, multi-agent learning in complex environments is a critical area of research for the next generation of AI, particularly in the context of cooperative tasks. Cooperative multi-agent learning is an essential problem for practitioners to consider as it has the potential to enable a wide range of multi-agent tasks.
In this presentation, we will review the background and challenges of cooperative multi-agent learning, and survey our research that aims to address these challenges.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Du, Yali}, year={2024}, month={Jul.}, pages={15436-15436} }

@article{Tao_Bao_Tang_Wu_Wei_Tian_2023, title={DE-net: Dynamic Text-Guided Image Editing Adversarial Networks}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26189}, DOI={10.1609/aaai.v37i8.26189}, abstractNote={Text-guided image editing models have shown remarkable results. However, there remain two problems. First, they employ fixed manipulation modules for various editing requirements (e.g., color changing, texture changing, content adding and removing), which results in over-editing or insufficient editing. Second, they do not clearly distinguish between text-required and text-irrelevant parts, which leads to inaccurate editing.
To solve these limitations, we propose:
(i) a Dynamic Editing Block (DEBlock) that composes different editing modules dynamically for various editing requirements.
(ii) a Composition Predictor (Comp-Pred), which predicts the composition weights for DEBlock according to the inference on target texts and source images.
(iii) a Dynamic text-adaptive Convolution Block (DCBlock) that queries source image features to distinguish text-required parts and text-irrelevant parts.
Extensive experiments demonstrate that our DE-Net achieves excellent performance and manipulates source images more correctly and accurately.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tao, Ming and Bao, Bing-Kun and Tang, Hao and Wu, Fei and Wei, Longhui and Tian, Qi}, year={2023}, month={Jun.}, pages={9971-9979} }

@article{Sun_Su_Wu_2023, title={DENet: Disentangled Embedding Network for Visible Watermark Removal}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25337}, DOI={10.1609/aaai.v37i2.25337}, abstractNote={Adding visible watermark into image is a common copyright protection method of medias. Meanwhile, public research on watermark removal can be utilized as an adversarial technology to help the further development of watermarking. Existing watermark removal methods mainly adopt multi-task learning networks, which locate the watermark and restore the background simultaneously. However, these approaches view the task as an image-to-image reconstruction problem, where they only impose supervision after the final output, making the high-level semantic features shared between different tasks. To this end, inspired by the two-stage coarse-refinement network, we propose a novel contrastive learning mechanism to disentangle the high-level embedding semantic information of the images and watermarks, driving the respective network branch more oriented.
Specifically, the proposed mechanism is leveraged for watermark image decomposition, which aims to decouple the clean image and watermark hints in the high-level embedding space. This can guarantee the learning representation of the restored image enjoy more task-specific cues.
In addition, we introduce a self-attention-based enhancement module, which promotes the network’s ability to capture semantic information among different regions, leading to further improvement on the contrastive learning mechanism. To validate the effectiveness of our proposed method, extensive experiments are conducted on different challenging benchmarks. Experimental evaluations show that our approach can achieve state-of-the-art performance and yield high-quality images. The code is available at: https://github.com/lianchengmingjue/DENet.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Sun, Ruizhou and Su, Yukun and Wu, Qingyao}, year={2023}, month={Jun.}, pages={2411-2419} }

@article{Burgess_Gretton_Milthorpe_Croak_Willingham_Tiu_2024, title={Dagster: Parallel Structured Search}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27060}, DOI={10.1609/aaai.v37i13.27060}, abstractNote={We demonstrate Dagster, a system that implements a new approach to scheduling interdependent (Boolean) SAT search activities in high-performance computing (HPC) environments.
Our system takes as input a set of disjunctive clauses (i.e., DIMACS CNF) and a labelled directed acyclic graph (DAG) structure describing how the clauses are decomposed into a set of interrelated problems.
Component problems are solved using standard systematic backtracking search, which may optionally be coupled to (stochastic dynamic) local search and/or clause-strengthening processes.
We demonstrate Dagster using a new Graph Maximal Determinant combinatorial case study. This demonstration paper presents a new case study, and is adjunct to the longer accepted manuscript at the Pacific Rim International Conference on Artificial Intelligence (2022).}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Burgess, Mark Alexander and Gretton, Charles and Milthorpe, Josh and Croak, Luke and Willingham, Thomas and Tiu, Alwen}, year={2024}, month={Jul.}, pages={16404-16406} }

@article{Rossolini_Nesti_Brau_Biondi_Buttazzo_2023, title={Defending from Physically-Realizable Adversarial Attacks through Internal Over-Activation Analysis}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26758}, DOI={10.1609/aaai.v37i12.26758}, abstractNote={This work presents Z-Mask, an effective and deterministic strategy to improve the adversarial robustness of convolutional networks against physically-realizable adversarial attacks.
The presented defense relies on specific Z-score analysis performed on the internal network features to detect and mask the pixels corresponding to adversarial objects in the input image. To this end, spatially contiguous activations are examined in shallow and deep layers to suggest potential adversarial regions. Such proposals are then aggregated through a multi-thresholding mechanism.
The effectiveness of Z-Mask is evaluated with an extensive set of experiments carried out on models for semantic segmentation and object detection. The evaluation is performed with both digital patches added to the input images and printed patches in the real world.
The results confirm that Z-Mask outperforms the state-of-the-art methods in terms of detection accuracy and overall performance of the networks under attack.
Furthermore, Z-Mask preserves its robustness against defense-aware attacks, making it suitable for safe and secure AI applications.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Rossolini, Giulio and Nesti, Federico and Brau, Fabio and Biondi, Alessandro and Buttazzo, Giorgio}, year={2023}, month={Jun.}, pages={15064-15072} }

@article{Gao_2024, title={Distributed Stochastic Nested Optimization for Emerging Machine Learning Models: Algorithm and Theory}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26804}, DOI={10.1609/aaai.v37i13.26804}, abstractNote={Traditional machine learning models can be formulated as the expected risk minimization (ERM) problem:
minw∈Rd Eξ [l(w; ξ)], where w ∈ Rd denotes the model parameter, ξ represents training samples, l(·) is the loss function. Numerous optimization algorithms, such as stochastic gradient descent (SGD), have been developed to solve the ERM problem. However, a wide range of emerging machine learning models are beyond this class of optimization problems, such as model-agnostic meta-learning (Finn, Abbeel, and Levine 2017). Of particular interest of my research is the stochastic nested optimization (SNO) problem, whose objective function has a nested structure. Specifically, I have been focusing on two instances of this kind of problem: stochastic compositional optimization (SCO) problems, which cover meta-learning, area-under-the-precision recall-curve optimization, contrastive self-supervised learning, etc., and stochastic bilevel optimization (SBO) problems, which can be applied to meta-learning, hyperparameter optimization, neural network architecture search, etc.
With the emergence of large-scale distributed data, such as the user data generated on mobile devices or intelligent hardware, it is imperative to develop distributed optimization algorithms for SNO (Distributed SNO). A significant challenge for optimizing distributed SNO problems lies in that the stochastic (hyper-)gradient is a biased estimation of the full gradient. Thus, existing distributed optimization algorithms when applied to them suffer from slow convergence rates. In this talk, I will discuss my recent works about distributed SCO (Gao and Huang 2021; Gao, Li, and Huang 2022) and distributed SBO (Gao, Gu, and Thai 2022; Gao 2022) under both centralized and decentralized settings, including algorithmic details about reducing the bias of stochastic gradient, theoretical convergence rate, and practical machine learning applications, and then highlight challenges for future research.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gao, Hongchang}, year={2024}, month={Jul.}, pages={15437-15437} }

@article{Wołosiuk_Świechowski_Mańdziuk_2023, title={Don’t Predict Counterfactual Values, Predict Expected Values Instead}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25661}, DOI={10.1609/aaai.v37i4.25661}, abstractNote={Counterfactual Regret Minimization algorithms are the most popular way of estimating the Nash Equilibrium in imperfect-information zero-sum games.
In particular, DeepStack -- the state-of-the-art Poker bot -- employs the so-called Deep Counterfactual Value Network (DCVN) to learn the Counterfactual Values (CFVs) associated with various states in the game.
Each CFV is a multiplication of two factors: (1) the probability that the opponent would reach a given state in a game, which can be explicitly calculated from the input data, and (2) the expected value (EV) of a payoff in that state, which is a complex function of the input data, hard to calculate.
In this paper, we propose a simple yet powerful modification to the CFVs estimation process, which consists in utilizing a deep neural network to estimate only the EV factor of CFV. This new target setting significantly simplifies the learning problem and leads to much more accurate CFVs estimation. A direct comparison, in terms of CFVs prediction losses, shows a significant prediction accuracy improvement of the proposed approach (DEVN) over the original DCVN formulation (relatively by 9.18-15.70% when using card abstraction, and by 3.37-8.39% without card abstraction, depending on a particular setting). Furthermore, the application of DEVN improves the theoretical lower bound of the error by 29.05-31.83% compared to the DCVN pipeline when card abstraction is applied.
Additionally, DEVN is able to achieve the goal using significantly smaller, and faster to infer, networks.
While the proposed modification may seem to be of a rather technical nature, it, in fact, presents a fundamentally different approach to the overall process of learning and estimating CFVs, since the distributions of the training signals differ significantly between DCVN and DEVN. The former estimates CFVs, which are biased by the probability of reaching a given game state, while training the latter relies on a direct EV estimation, regardless of the state probability. In effect, the learning signal of DEVN presents a better estimation of the true value of a given state, thus allowing more accurate CFVs estimation.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wołosiuk, Jeremiasz and Świechowski, Maciej and Mańdziuk, Jacek}, year={2023}, month={Jun.}, pages={5303-5311} }

@article{Ali_Bhagat_Banerjee_Prasad_2024, title={Efficient Algorithms for Regret Minimization in Billboard Advertisement (Student Abstract)}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26934}, DOI={10.1609/aaai.v37i13.26934}, abstractNote={Now-a-days, billboard advertisement has emerged as an effective outdoor advertisement technique. In this case, a commercial house approaches an influence provider for a specific number of views of their advertisement content on a payment basis. If the influence provider can satisfy this then they will receive the full payment else a partial payment. If the influence provider provides more or less than the demand then
certainly this is a loss to them. This is formalized as ‘Regret’
and the goal of the influence provider will be to minimize
the ‘Regret’. In this paper, we propose simple and efficient
solution methodologies to solve this problem. Efficiency and
effectiveness have been demonstrated by experimentation.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ali, Dildar and Bhagat, Ankit Kumar and Banerjee, Suman and Prasad, Yamuna}, year={2024}, month={Jul.}, pages={16148-16149} }

@article{Vahidian_Morafah_Wang_Kungurtsev_Chen_Shah_Lin_2023, title={Efficient Distribution Similarity Identification in Clustered Federated Learning via Principal Angles between Client Data Subspaces}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26197}, DOI={10.1609/aaai.v37i8.26197}, abstractNote={Clustered federated learning (FL) has been shown to produce promising results by grouping clients into clusters.
This is especially effective in scenarios where separate groups of clients have significant differences in the distributions of their local data. Existing clustered FL algorithms are essentially trying to group together clients with similar distributions so that clients in the same cluster can leverage each other’s data to better perform federated learning. However, prior clustered FL algorithms attempt to learn these distribution similarities indirectly during training, which can be quite time consuming as many rounds of federated learning may be required until the formation of clusters is stabilized. In this paper, we propose a new approach to federated learning that directly aims to efficiently identify distribution similarities among clients by analyzing the principal angles between the client data subspaces. Each client applies a truncated singular value decomposition (SVD) step on its local data in a single-shot manner to derive a small set of principal vectors, which provides a signature that succinctly captures the main characteristics of the underlying distribution.
This small set of principal vectors is provided to the server so that the server can directly identify distribution similarities among the clients to form clusters.
This is achieved by comparing the similarities of the principal angles between the client data subspaces spanned by those principal vectors. The approach provides a simple, yet effective clustered FL framework that addresses a broad range of data heterogeneity issues beyond simpler forms of Non-IIDness like label skews. Our clustered FL approach also enables convergence guarantees for non-convex objectives.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Vahidian, Saeed and Morafah, Mahdi and Wang, Weijia and Kungurtsev, Vyacheslav and Chen, Chen and Shah, Mubarak and Lin, Bill}, year={2023}, month={Jun.}, pages={10043-10052} }

@article{Potyka_Yin_Toni_2023, title={Explaining Random Forests Using Bipolar Argumentation and Markov Networks}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26132}, DOI={10.1609/aaai.v37i8.26132}, abstractNote={Random forests are decision tree ensembles that can be used to solve a variety of machine learning problems. However, as
the number of trees and their individual size can be large,
their decision making process is often incomprehensible.
We show that their decision process can be naturally represented as an argumentation problem, which allows creating global explanations via argumentative reasoning. We generalize sufficient and necessary argumentative explanations using a Markov network encoding, discuss the relevance of these explanations and establish relationships to
families of abductive explanations from the literature. As the complexity of the explanation problems is high, we present an efficient approximation algorithm with probabilistic approximation guarantees.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Potyka, Nico and Yin, Xiang and Toni, Francesca}, year={2023}, month={Jun.}, pages={9453-9460} }

