@article{Wu_Huang_Ding_Wang_Wang_Xu_2023, title={FedNP: Towards Non-IID Federated Learning via Federated Neural Propagation}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26237}, DOI={10.1609/aaai.v37i9.26237}, abstractNote={Traditional federated learning (FL) algorithms, such as FedAvg, fail to handle non-i.i.d data because they learn a global model by simply averaging biased local models that are trained on non-i.i.d local data, therefore failing to model the global data distribution. In this paper, we present a novel Bayesian FL algorithm that successfully handles such a non-i.i.d FL setting by enhancing the local training task with an auxiliary task that explicitly estimates the global data distribution. One key challenge in estimating the global data distribution is that the data are partitioned in FL, and therefore the ground-truth global data distribution is inaccessible.
To address this challenge, we propose an expectation-propagation-inspired probabilistic neural network, dubbed federated neural propagation (FedNP), which efficiently estimates the global data distribution given non-i.i.d data partitions. Our algorithm is sampling-free and end-to-end differentiable, can be applied with any conventional FL frameworks and learns richer global data representation.
Experiments on both image classification tasks with synthetic non-i.i.d image data partitions and real-world non-i.i.d speech recognition tasks demonstrate that our framework effectively alleviates the performance deterioration caused by non-i.i.d data.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Xueyang and Huang, Hengguan and Ding, Youlong and Wang, Hao and Wang, Ye and Xu, Qian}, year={2023}, month={Jun.}, pages={10399-10407} }

@article{Ye_Cao_Chen_Xu_Zou_2023, title={FiTs: Fine-Grained Two-Stage Training for Knowledge-Aware Question Answering}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26629}, DOI={10.1609/aaai.v37i11.26629}, abstractNote={Knowledge-aware question answering (KAQA) requires the model to answer questions over a knowledge base, which is essential for both open-domain QA and domain-specific QA, especially when language models alone cannot provide all the knowledge needed.
Despite the promising result of recent KAQA systems which tend to integrate linguistic knowledge from pre-trained language models (PLM) and factual knowledge from knowledge graphs (KG) to answer complex questions, a bottleneck exists in effectively fusing the representations from PLMs and KGs because of (i) the semantic and distributional gaps between them, and (ii) the difficulties in joint reasoning over the provided knowledge from both modalities.
To address the above two problems, we propose a Fine-grained Two-stage training framework (FiTs) to boost the KAQA system performance: The first stage aims at aligning representations from the PLM and the KG, thus bridging the modality gaps between them, named knowledge adaptive post-training. The second stage, called knowledge-aware fine-tuning, aims to improve the model’s joint reasoning ability based on the aligned representations.
In detail, we fine-tune the post-trained model via two auxiliary self-supervised tasks in addition to the QA supervision.
Extensive experiments demonstrate that our approach achieves state-of-the-art performance on three benchmarks in the commonsense reasoning (i.e., CommonsenseQA, OpenbookQA) and medical question answering (i.e., MedQA-USMILE) domains.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ye, Qichen and Cao, Bowen and Chen, Nuo and Xu, Weiyuan and Zou, Yuexian}, year={2023}, month={Jun.}, pages={13914-13922} }

@article{Ramos-Carreño_2024, title={Fuzzy C-means: Differences on Clustering Behavior between High Dimensional and Functional Data (Student Abstract)}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27015}, DOI={10.1609/aaai.v37i13.27015}, abstractNote={Fuzzy c-means (FCM) is a generalization of the classical k-means clustering algorithm to the case where an observation can belong to several clusters at the same time.
The algorithm was previously observed to have initialization problems when the number of desired clusters or the number of dimensions of the data are high.
We have tested FCM against clustering problems with functional data, generated from stationary Gaussian processes, and thus in principle infinite-dimensional.
We observed that when the data is more functional in nature, which can be obtained by tuning the length-scale parameter of the Gaussian process, the aforementioned problems do not appear.
This not only indicates that FCM is suitable as a clustering method for functional data, but also illustrates how functional data differs from traditional multivariate data.
In addition this seems to suggest a qualitative way to measure the latent dimensionality of the functional distribution itself.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ramos-Carreño, Carlos}, year={2024}, month={Jul.}, pages={16310-16311} }

@article{Rajaby Faghihi_Nafar_Zheng_Mirzaee_Zhang_Uszok_Wan_Premsri_Roth_Kordjamshidi_2023, title={GLUECons: A Generic Benchmark for Learning under Constraints}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26143}, DOI={10.1609/aaai.v37i8.26143}, abstractNote={Recent research has shown that integrating domain knowledge into deep learning architectures is effective; It helps reduce the amount of required data, improves the accuracy of the models’ decisions, and improves the interpretability of models. However, the research community lacks a convened benchmark for systematically evaluating knowledge integration methods.
In this work, we create a benchmark that is a collection of nine tasks in the domains of natural language processing and computer vision. In all cases, we model external knowledge as constraints, specify the sources of the constraints for each task, and implement various models that use these constraints.
We report the results of these models using a new set of extended evaluation criteria in addition to the task performances for a more in-depth analysis. This effort provides a framework for a more comprehensive and systematic comparison of constraint integration techniques and for identifying related research challenges. It will facilitate further research for alleviating some problems of state-of-the-art neural models.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Rajaby Faghihi, Hossein and Nafar, Aliakbar and Zheng, Chen and Mirzaee, Roshanak and Zhang, Yue and Uszok, Andrzej and Wan, Alexander and Premsri, Tanawan and Roth, Dan and Kordjamshidi, Parisa}, year={2023}, month={Jun.}, pages={9552-9561} }

@article{Mao_Wan_Wen_Wu_Zheng_Qiang_Guo_Wu_Hu_Lin_2024, title={GMDNet: A Graph-Based Mixture Density Network for Estimating Packages’ Multimodal Travel Time Distribution}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25578}, DOI={10.1609/aaai.v37i4.25578}, abstractNote={&lt;p&gt;In the logistics network, accurately estimating packages’ Travel Time Distribution (TTD) given the routes greatly benefits both consumers and platforms. Although recent works perform well in predicting an expected time or a time distribution in a road network, they could not be well applied to estimate TTD in logistics networks. Because TTD prediction in the logistics network requires modeling packages’ multimodal TTD (MTTD, i.e., there can be more than one likely output with a given input) while leveraging the complex correlations in the logistics network. To this end, this work opens appealing research opportunities in studying MTTD learning conditioned on graph-structure data by investigating packages’ travel time distribution in the logistics network. We propose a Graph-based Mixture Density Network, named GMDNet, which takes the benefits of both graph neural network and mixture density network for estimating MTTD conditioned on graph-structure data (i.e., the logistics network). Furthermore, we adopt the Expectation-Maximization (EM) framework in the training process to guarantee local convergence and thus obtain more stable results than gradient descent. Extensive experiments on two real-world datasets demonstrate the superiority of our proposed model.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Corrigendum Notice&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;In the initial publication of this article, the authors &lt;span style=&quot;margin: 0px; padding: 0px;&quot;&gt;(Mao et al. 2023) acknowledged that although it referred to an earlier paper already presented and published in ICML-21 (Errica et al. 2021), it insufficiently acknowledged the extent to which it incorporated and made extensive use of techniques therein. We are providing a &lt;em&gt;Corrigendum Note&lt;/em&gt;, &quot;PDF (2024-09-25),&quot;&lt;/span&gt; alongside the original published version. The &lt;em&gt;Corrigendum Note&lt;/em&gt; summarizes the main novel contributions of this paper.&lt;/p&gt;
&lt;p&gt;Errica, F.; Bacciu, D.; and Micheli, A. 2021. Graph Mixture Density Networks. In Proceedings of the 38th International Conference on Machine Learning (PMLR-28), 3025–3035. PMLR.&lt;br /&gt;&lt;br /&gt;Mao, X.; Wan, H.; Wen, H.; Wu, F.; Zheng, J.; Qiang, Y.; Guo, S.; Wu, L.; Hu, H.; and Lin, Y. 2023. GMDNet: A Graph-Based Mixture Density Network for Estimating Packages’ Multimodal Travel Time Distribution. In Proceedings of the 37th AAAI Conference on Artificial Intelligence.&lt;/p&gt;}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mao, Xiaowei and Wan, Huaiyu and Wen, Haomin and Wu, Fan and Zheng, Jianbin and Qiang, Yuting and Guo, Shengnan and Wu, Lixia and Hu, Haoyuan and Lin, Youfang}, year={2024}, month={Sep.}, pages={4561-4568} }

@article{Gollapalli_Du_Ng_2024, title={Generating Reflective Questions for Engaging Gallery Visitors in ArtMuse}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27070}, DOI={10.1609/aaai.v37i13.27070}, abstractNote={Human guides in museums and galleries are professionally trained to stimulate informal learning in visitors by asking low-risk, open-ended reflective questions
that enable them to
focus on specific features of artifacts, relate to prior experiences, and elicit curiosity as well as further thought. We present ArtMuse, our AI-powered chatbot for asking reflective questions in context of paintings. Our reflective question generation model in ArtMuse
was trained by applying a
novel combination of existing models for
extractive question answering and open-domain chitchat. User evaluation studies indicate that we are able to generate fluent and specific reflective questions for paintings that are highly-engaging.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gollapalli, Sujatha Das and Du, Mingzhe and Ng, See-Kiong}, year={2024}, month={Jul.}, pages={16434-16436} }

@article{Xie_Yangning_Chen_Ouyang_Xie_Zheng_2023, title={Global Mixup: Eliminating Ambiguity with Clustering}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26616}, DOI={10.1609/aaai.v37i11.26616}, abstractNote={Data augmentation with Mixup has been proven an effective method to regularize the current deep neural networks. Mixup generates virtual samples and corresponding labels simultaneously by linear interpolation. However, the one-stage generation paradigm and the use of linear interpolation have two defects: (1) The label of the generated sample is simply combined from the labels of the original sample pairs without reasonable judgment, resulting in ambiguous labels. (2) Linear combination significantly restricts the sampling space for generating samples. To address these issues, we propose a novel and effective augmentation method, Global Mixup, based on global clustering relationships.
Specifically, we transform the previous one-stage augmentation process into two-stage by decoupling the process of generating virtual samples from the labeling. And for the labels of the generated samples, relabeling is performed based on clustering by calculating the global relationships of the generated samples.
Furthermore, we are no longer restricted to linear relationships, which allows us to generate more reliable virtual samples in a larger sampling space.
Extensive experiments for CNN, LSTM, and BERT on five tasks show that Global Mixup outperforms previous baselines. Further experiments also demonstrate the advantage of Global Mixup in low-resource scenarios.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Xie, Xiangjin and Yangning, Li and Chen, Wang and Ouyang, Kai and Xie, Zuotong and Zheng, Hai-Tao}, year={2023}, month={Jun.}, pages={13798-13806} }

@article{Li_Chen_Huang_2023, title={Implicit Stochastic Gradient Descent for Training Physics-Informed Neural Networks}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26046}, DOI={10.1609/aaai.v37i7.26046}, abstractNote={Physics-informed neural networks (PINNs) have effectively been demonstrated in solving forward and inverse differential equation problems,
but they are still trapped in training failures when the target functions to be approximated exhibit high-frequency or multi-scale features.
In this paper, we propose to employ implicit stochastic gradient descent (ISGD) method to train PINNs for improving the stability of training process.
We heuristically analyze how ISGD overcome stiffness in the gradient flow dynamics of PINNs, especially for problems with multi-scale solutions.
We theoretically prove that for two-layer fully connected neural networks with large hidden nodes, randomly initialized ISGD converges to a globally optimal solution for the quadratic loss function.
Empirical results demonstrate that ISGD works well in practice and compares favorably to other gradient-based optimization methods such as SGD and Adam, while can also effectively address the numerical stiffness in training dynamics via gradient descent.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Ye and Chen, Song-Can and Huang, Sheng-Jun}, year={2023}, month={Jun.}, pages={8692-8700} }

