@article{Cerrato_Köppel_Esposito_Kramer_2023, title={Invariant Representations with Stochastically Quantized Neural Networks}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25851}, DOI={10.1609/aaai.v37i6.25851}, abstractNote={Representation learning algorithms offer the opportunity to learn invariant representations of the input data with regard to nuisance factors.
Many authors have leveraged such strategies to learn fair representations, i.e., vectors where information about sensitive attributes is removed. These methods are attractive as they may be interpreted as minimizing the mutual information between a neural layer’s activations and a sensitive attribute.
However, the theoretical grounding of such methods relies either on the computation of infinitely accurate adversaries or on minimizing a variational upper bound of a mutual information estimate.
In this paper, we propose a methodology for direct computation of the mutual information between neurons in a layer and a sensitive attribute. We employ stochastically-activated binary neural networks, which lets us treat neurons as random variables.
Our method is therefore able to minimize an upper bound on the mutual information between the neural representations and a sensitive attribute.
We show that this method compares favorably with the state of the art in fair representation learning and that the learned representations display a higher level of invariance compared to full-precision neural networks.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cerrato, Mattia and Köppel, Marius and Esposito, Roberto and Kramer, Stefan}, year={2023}, month={Jun.}, pages={6962-6970} }

@article{Shang_Zeng_Qiao_Wang_Zhang_Sun_Patel_Fu_2023, title={JR2Net: Joint Monocular 3D Face Reconstruction and Reenactment}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25314}, DOI={10.1609/aaai.v37i2.25314}, abstractNote={Face reenactment and reconstruction benefit various applications in self-media, VR, etc. Recent face reenactment methods use 2D facial landmarks to implicitly retarget facial expressions and poses from driving videos to source images,
while they suffer from pose and expression preservation issues for cross-identity scenarios, i.e., when the source and the driving subjects are different. Current self-supervised face reconstruction methods also demonstrate impressive results.
However, these methods do not handle large expressions well, since their training data lacks samples of large expressions, and 2D facial attributes are inaccurate on such samples. To mitigate the above problems, we propose to explore the inner connection between the two tasks, i.e., using face reconstruction to provide sufficient 3D information for reenactment, and synthesizing videos paired with captured face model parameters through face reenactment to enhance the
expression module of face reconstruction. In particular, we propose a novel cascade framework named JR2Net for Joint Face Reconstruction and Reenactment, which begins with the training of a coarse reconstruction network, followed by a 3D-aware face reenactment network based on the coarse reconstruction results. In the end, we train an expression tracking network based on our synthesized videos composed by image-face model parameter pairs. Such an expression tracking network can further enhance the coarse face reconstruction. Extensive experiments show that our JR2Net outperforms the state-of-the-art methods on several face reconstruction and reenactment benchmarks.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shang, Jiaxiang and Zeng, Yu and Qiao, Xin and Wang, Xin and Zhang, Runze and Sun, Guangyuan and Patel, Vishal and Fu, Hongbo}, year={2023}, month={Jun.}, pages={2200-2208} }

@article{Rossiello_Chowdhury_Mihindukulasooriya_Cornec_Gliozzo_2024, title={KnowGL: Knowledge Generation and Linking from Text}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27084}, DOI={10.1609/aaai.v37i13.27084}, abstractNote={We propose KnowGL, a tool that allows converting text into structured relational data represented as a set of ABox assertions compliant with the TBox of a given Knowledge Graph (KG), such as Wikidata. We address this problem as a sequence generation task by leveraging pre-trained sequence-to-sequence language models, e.g. BART.
Given a sentence, we fine-tune such models to detect pairs of entity mentions and jointly generate a set of facts consisting of the full set of semantic annotations for a KG, such as entity labels, entity types, and their relationships.
To showcase the capabilities of our tool, we build a web application consisting of a set of UI widgets that help users to navigate through the semantic data extracted from a given input text. We make the KnowGL model available at https://huggingface.co/ibm/knowgl-large.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Rossiello, Gaetano and Chowdhury, Md. Faisal Mahbub and Mihindukulasooriya, Nandana and Cornec, Owen and Gliozzo, Alfio Massimiliano}, year={2024}, month={Jul.}, pages={16476-16478} }

@article{Gauthier_Urban_2023, title={Learning Program Synthesis for Integer Sequences from Scratch}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25930}, DOI={10.1609/aaai.v37i6.25930}, abstractNote={We present a self-learning approach for synthesizing programs from integer
sequences. Our method relies on a tree search guided by a learned policy. Our system is tested on the On-Line Encyclopedia of Integer Sequences.
There, it discovers, on its own, solutions for 27987 sequences starting from basic operators and without human-written training examples.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gauthier, Thibault and Urban, Josef}, year={2023}, month={Jun.}, pages={7670-7677} }

@article{Mashiah_Attias_Mansour_2023, title={Learning Revenue Maximization Using Posted Prices for Stochastic Strategic Patient Buyers}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26091}, DOI={10.1609/aaai.v37i8.26091}, abstractNote={We consider a seller faced with buyers which have the ability to delay their decision, which we call patience.
Each buyer’s type is composed of value and patience, and it is sampled i.i.d. from a distribution.
The seller, using posted prices, would like to maximize her revenue from selling to the buyer. In this paper, we formalize this setting and characterize the resulting Stackelberg equilibrium, where the seller first commits to her strategy, and then the buyers best respond. Following this, we show how to compute both the optimal pure and mixed strategies. We then consider a learning setting, where the seller does not have access to the distribution over buyer’s types. Our main results are the following. We derive a sample complexity bound for the learning of an approximate optimal pure strategy, by computing the fat-shattering dimension of this setting. Moreover, we provide a general sample complexity bound for the approximate optimal mixed strategy. We also consider an online setting and derive a vanishing regret bound with respect to both the optimal pure strategy and the optimal mixed strategy.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mashiah, Eitan-Hai and Attias, Idan and Mansour, Yishay}, year={2023}, month={Jun.}, pages={9090-9098} }

@article{Jia_Li_Yu_Bian_Zhao_Li_Xiong_Dou_2023, title={Learning from Training Dynamics: Identifying Mislabeled Data beyond Manually Designed Features}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25972}, DOI={10.1609/aaai.v37i7.25972}, abstractNote={While mislabeled or ambiguously-labeled samples in the training set could negatively affect the performance of deep models, diagnosing the dataset and identifying mislabeled samples helps to improve the generalization power. Training dynamics, i.e., the traces left by iterations of optimization algorithms, have recently been proved to be effective to localize mislabeled samples with hand-crafted features.
In this paper, beyond manually designed features, we introduce a novel learning-based solution, leveraging a noise detector, instanced by an LSTM network, which learns to predict whether a sample was mislabeled using the raw training dynamics as input. Specifically, the proposed method trains the noise detector in a supervised manner using the dataset with synthesized label noises and can adapt to various datasets (either naturally or synthesized label-noised) without retraining. We conduct extensive experiments to evaluate the proposed method.
We train the noise detector based on the synthesized label-noised CIFAR dataset and test such noise detector on Tiny ImageNet, CUB-200, Caltech-256, WebVision and Clothing1M. Results show that the proposed method precisely detects mislabeled samples on various datasets without further adaptation, and outperforms state-of-the-art methods.
Besides, more experiments demonstrate that the mislabel identification can guide a label correction, namely data debugging, providing orthogonal improvements of algorithm-centric state-of-the-art techniques from the data aspect.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Jia, Qingrui and Li, Xuhong and Yu, Lei and Bian, Jiang and Zhao, Penghao and Li, Shupeng and Xiong, Haoyi and Dou, Dejing}, year={2023}, month={Jun.}, pages={8041-8049} }

@article{Chen_Li_Zhang_Xia_Wei_Cui_Gao_Zhang_Yan_2023, title={Learning towards Selective Data Augmentation for Dialogue Generation}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26491}, DOI={10.1609/aaai.v37i11.26491}, abstractNote={As it is cumbersome and expensive to acquire a huge amount of data for training neural dialog models, data augmentation is proposed to effectively utilize existing training samples.
However, current data augmentation techniques on the dialog generation task mostly augment all cases in the training dataset without considering the intrinsic attributes between different cases.
We argue that not all cases are beneficial for augmentation task, and the cases suitable for augmentation should obey the following two attributes: (1) low-quality (the dialog model cannot generate a high-quality response for the case),
(2) representative (the case should represent the property of the whole dataset).
Herein, we explore this idea by proposing a Selective Data Augmentation framework (SDA) for the response generation task.
SDA employs a dual adversarial network to select the lowest quality and most representative data points for augmentation in one stage. Extensive experiments conducted on two publicly available datasets, i.e., DailyDialog and OpenSubtitles, show that our framework can improve the response generation performance with respect to various metrics}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Xiuying and Li, Mingzhe and Zhang, Jiayi and Xia, Xiaoqiang and Wei, Chen and Cui, Jianwei and Gao, Xin and Zhang, Xiangliang and Yan, Rui}, year={2023}, month={Jun.}, pages={12673-12681} }

@article{Liu_Feng_Liu_Stone_2023, title={Metric Residual Network for Sample Efficient Goal-Conditioned Reinforcement Learning}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26058}, DOI={10.1609/aaai.v37i7.26058}, abstractNote={Goal-conditioned reinforcement learning (GCRL) has a wide range of potential real-world applications, including manipulation and navigation problems in robotics. Especially in such robotics tasks, sample efficiency is of the utmost importance for GCRL since, by default, the agent is only rewarded when it reaches its goal. While several methods have been proposed to improve the sample efficiency of GCRL, one relatively under-studied approach is the design of neural architectures to support sample efficiency.
In this work, we introduce a novel neural architecture for GCRL that achieves significantly better sample efficiency than the commonly-used monolithic network architecture. The key insight is that the optimal action-value function must satisfy the triangle inequality in a specific sense.
Furthermore, we introduce the metric residual network (MRN) that deliberately decomposes the action-value function into the negated summation of a metric plus a residual asymmetric component. MRN provably approximates any optimal action-value function, thus making it a fitting neural architecture for GCRL.
We conduct comprehensive experiments across 12 standard benchmark environments in GCRL. The empirical results demonstrate that MRN uniformly outperforms other state-of-the-art GCRL neural architectures in terms of sample efficiency. The code is available at https://github.com/Cranial-XIX/metric-residual-network.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Bo and Feng, Yihao and Liu, Qiang and Stone, Peter}, year={2023}, month={Jun.}, pages={8799-8806} }

@article{Mullick_2024, title={Novel Intent Detection and Active Learning Based Classification (Student Abstract)}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27003}, DOI={10.1609/aaai.v37i13.27003}, abstractNote={Novel intent class detection is an important problem in real world scenario for conversational agents for continuous interaction. Several research works have been done to detect novel intents in a mono-lingual (primarily English) texts and
images. But, current systems lack an end-to-end universal framework to detect novel intents across various different languages with less human annotation effort for mis-classified and system rejected samples. This paper proposes
NIDAL (Novel Intent Detection and Active Learning based
classification), a semi-supervised framework to detect novel
intents while reducing human annotation cost. Empirical results on various benchmark datasets demonstrate that this system outperforms the baseline methods by more than 10%
margin for accuracy and macro-F1. The system achieves this while maintaining overall annotation cost to be just ~6-10% of the unlabeled data available to the system.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mullick, Ankan}, year={2024}, month={Jul.}, pages={16286-16287} }

@article{Becker_D’Angelo_Ghobadi_2023, title={On the Cost of Demographic Parity in Influence Maximization}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26651}, DOI={10.1609/aaai.v37i12.26651}, abstractNote={Modeling and shaping how information spreads through a network is a major research topic in network analysis. While initially the focus has been mostly on efficiency, recently fairness criteria have been taken into account in this setting.
Most work has focused on the maximin criteria however, and thus still different groups can receive very different shares of information. In this work we propose to consider fairness as a notion to be guaranteed by an algorithm rather than as a criterion to be maximized. To this end, we propose three optimization problems that aim at maximizing the overall spread while enforcing strict levels of demographic parity fairness via constraints (either ex-post or ex-ante). The level of fairness hence becomes a user choice rather than a property to be observed upon output. We study this setting from various perspectives.
First, we prove that the cost of introducing demographic parity can be high in terms of both overall spread and computational complexity, i.e., the price of fairness may be unbounded for all three problems and optimal solutions are hard to compute, in some case even approximately or when fairness constraints may be violated. For one of our problems, we still design an algorithm with both constant approximation factor and fairness violation.
We also give two heuristics that allow the user to choose the tolerated fairness violation. By means of an extensive experimental study, we show that our algorithms perform well in practice, that is, they achieve the best demographic parity fairness values. For certain instances we additionally even obtain an overall spread comparable to the most efficient algorithms that come without any fairness guarantee, indicating that the empirical price of fairness may actually be small when using our algorithms.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Becker, Ruben and D’Angelo, Gianlorenzo and Ghobadi, Sajjad}, year={2023}, month={Jun.}, pages={14110-14118} }

@article{Russo_Proutiere_2023, title={On the Sample Complexity of Representation Learning in Multi-Task Bandits with Global and Local Structure}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26155}, DOI={10.1609/aaai.v37i8.26155}, abstractNote={We investigate the sample complexity of learning the optimal arm for multi-task bandit problems. Arms consist of two components: one that is shared across tasks (that we call representation) and one that is task-specific (that we call predictor). The objective is to learn the optimal (representation, predictor)-pair for each task, under the assumption that the optimal representation is common to all tasks. Within this framework, efficient learning algorithms should transfer knowledge across tasks. We consider the best-arm identification problem with fixed confidence, where, in each round, the learner actively selects both a task, and an arm, and observes the corresponding reward.
We derive instance-specific sample complexity lower bounds, which apply to any algorithm that identifies the best representation, and the best predictor for a task, with prescribed confidence levels. We devise an algorithm, OSRL-SC, that can learn the optimal representation, and the optimal predictors, separately, and whose sample complexity approaches the lower bound. Theoretical and numerical results demonstrate that OSRL-SC achieves a better scaling with respect to the number of tasks compared to the classical best-arm identification algorithm.
The code can be found here https://github.com/rssalessio/OSRL-SC.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Russo, Alessio and Proutiere, Alexandre}, year={2023}, month={Jun.}, pages={9658-9667} }

@article{Levy_Mansour_2023, title={Optimism in Face of a Context:Regret Guarantees for Stochastic Contextual MDP}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26025}, DOI={10.1609/aaai.v37i7.26025}, abstractNote={We present regret minimization algorithms for stochastic contextual MDPs under minimum reachability assumption, using an access to an offline least square regression oracle.
We analyze three different settings: where the dynamics is known, where the dynamics is unknown but independent of the context and the most challenging setting where the dynamics is unknown and context-dependent. For the latter, our algorithm obtains regret bound (up to poly-logarithmic factors) of order (H+1/pₘᵢₙ)H|S|³ᐟ²(|A|Tlog(max{|?|,|?|} /?))¹ᐟ² with probability 1−?, where ? and ? are finite and realizable function classes used to approximate the dynamics and rewards respectively, pₘᵢₙ is the minimum reachability parameter, S is the set of states, A the set of actions, H the horizon, and T the number of episodes.
To our knowledge, our approach is the first optimistic approach applied to contextual MDPs with general function approximation (i.e., without additional knowledge regarding the function class, such as it being linear and etc.).
We present a lower bound of ?((TH|S||A|ln|?| /ln|A| )¹ᐟ² ), on the expected regret which holds even in the case of known dynamics.
Lastly, we discuss an extension of our results to CMDPs without minimum reachability, that obtains order of T³ᐟ⁴ regret.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Levy, Orin and Mansour, Yishay}, year={2023}, month={Jun.}, pages={8510-8517} }

@article{Chakraborty_Bedi_Tokekar_Koppel_Sadler_Huang_Manocha_2023, title={Posterior Coreset Construction with Kernelized Stein Discrepancy for Model-Based Reinforcement Learning}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25853}, DOI={10.1609/aaai.v37i6.25853}, abstractNote={Model-based approaches to reinforcement learning (MBRL) exhibit favorable performance in practice, but their theoretical guarantees in large spaces are mostly restricted to the setting when transition model is Gaussian or Lipschitz, and demands a posterior estimate whose representational complexity grows unbounded with time. In this work, we develop a novel MBRL method (i) which relaxes the assumptions on the target transition model to belong to a generic family of mixture models; (ii) is applicable to large-scale training by incorporating a compression step such that the posterior estimate consists of a Bayesian coreset of only statistically significant past state-action pairs; and (iii) exhibits a sublinear Bayesian regret.
To achieve these results, we adopt an approach based upon Stein’s method, which, under a smoothness condition on the constructed posterior and target, allows distributional distance to be evaluated in closed form as the kernelized Stein discrepancy (KSD). The aforementioned compression step is then computed in terms of greedily retaining only those samples which are more than a certain KSD away from the previous model estimate.
Experimentally, we observe that this approach is competitive with several state-of-the-art RL methodologies, and can achieve up-to 50 percent reduction in wall clock time in some continuous control environments.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chakraborty, Souradip and Bedi, Amrit Singh and Tokekar, Pratap and Koppel, Alec and Sadler, Brian and Huang, Furong and Manocha, Dinesh}, year={2023}, month={Jun.}, pages={6980-6988} }

@article{Lechner_Žikelić_Chatterjee_Henzinger_Rus_2023, title={Quantization-Aware Interval Bound Propagation for Training Certifiably Robust Quantized Neural Networks}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26747}, DOI={10.1609/aaai.v37i12.26747}, abstractNote={We study the problem of training and certifying adversarially robust quantized neural networks (QNNs). Quantization is a technique for making neural networks more efficient by running them using low-bit integer arithmetic and is therefore commonly adopted in industry. Recent work has shown that floating-point neural networks that have been verified to be robust can become vulnerable to adversarial attacks after quantization, and certification of the quantized representation is necessary to guarantee robustness.
In this work, we present quantization-aware interval bound propagation (QA-IBP), a novel method for training robust QNNs.
Inspired by advances in robust learning of non-quantized networks, our training algorithm computes the gradient of an abstract representation of the actual network. Unlike existing approaches, our method can handle the discrete semantics of QNNs. Based on QA-IBP, we also develop a complete verification procedure for verifying the adversarial robustness of QNNs, which is guaranteed to terminate and produce a correct answer. Compared to existing approaches, the key advantage of our verification procedure is that it runs entirely on GPU or other accelerator devices. We demonstrate experimentally that our approach significantly outperforms existing methods and establish the new state-of-the-art for training and certifying the robustness of QNNs.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lechner, Mathias and Žikelić, Đorđe and Chatterjee, Krishnendu and Henzinger, Thomas A. and Rus, Daniela}, year={2023}, month={Jun.}, pages={14964-14973} }

@article{Faella_Parlato_2023, title={Reachability Games Modulo Theories with a Bounded Safety Player}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25779}, DOI={10.1609/aaai.v37i5.25779}, abstractNote={Solving reachability games is a fundamental problem for the analysis, verification, and synthesis of reactive systems.
We consider logical reachability games modulo theories (in short, GMTs), i.e.,
infinite-state games whose rules are defined by logical formulas over a multi-sorted first-order theory. Our games have an asymmetric constraint: the safety player has at most k possible moves from each game configuration, whereas the reachability player has no such limitation.
Even though determining the winner of such a GMT is undecidable, it can be reduced to the well-studied problem of checking the satisfiability of a system of constrained Horn clauses (CHCs), for which many off-the-shelf solvers have been developed.
Winning strategies for GMTs can also be computed by resorting to suitable CHC queries. We demonstrate that GMTs can model various relevant real-world games, and that our approach can effectively solve several problems from different domains, using Z3 as the backend CHC solver.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Faella, Marco and Parlato, Gennaro}, year={2023}, month={Jun.}, pages={6330-6337} }

abstract:
The last few years have witnessed a renewed interest in “data-driven algorithm design” (Balcan 2020), the use of Machine Learning (ML) to tailor an algorithm to a distribution of instances. More than a decade ago, advances in algorithm configuration (Hoos 2011) paved the way for the use of historical data to modify an algorithm’s (typically fixed, static) parameters. In discrete optimization (e.g., satisfiability, integer programming, etc.), exact and inexact algorithms for NP-Hard problems often involve heuristic search decisions (Lodi 2013), abstracted as parameters, that can demonstrably benefit from tuning on historical instances from the application of interest.

While useful, algorithm configuration may be insufficient: setting the parameters of an algorithm upfront of solving the input instance is still a static, high-level decision. In contrast, we have been exploring a suite of ML and Reinforcement Learning (RL) approaches that tune iterative optimization algorithms, such as branch-and-bound for integer programming or construction heuristics, at the iteration-level (Khalil et al. 2016, 2017; Dai et al. 2017; Chmiela et al. 2021; Gupta et al. 2022; Chi et al. 2022; Khalil, Vaezipoor, and Dilkina 2022; Khalil, Morris, and Lodi 2022; Alomrani, Moravej, and Khalil 2022; Cappart et al. 2021; Gupta et al. 2020).

We will survey our most recent work in this area:
1. New methods for learning in MILP branch-and-bound (Gupta et al. 2020, 2022; Chmiela et al. 2021; Khalil, Vaezipoor, and Dilkina 2022; Khalil, Morris, and Lodi 2022);

2. RL for online combinatorial optimization and largescale linear programming (Alomrani, Moravej, and Khalil 2022; Chi et al. 2022);

3. Neural network approximations for stochastic programming (Dumouchelle et al. 2022).

