@article{Zong_Sun_2024, title={Retraction Note to: McOmet: Multimodal Fusion Transformer for Physical Audiovisual Commonsense Reasoning}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27728}, DOI={10.1609/aaai.v37i13.27728}, abstractNote={&lt;p&gt;This Retraction Note refers to: &lt;a href=&quot;https://doi.org/10.1609/aaai.v37i5.25813&quot;&gt;RETRACTED: McOmet: Multimodal Fusion Transformer for Physical Audiovisual Commonsense Reasoning.&lt;/a&gt;&lt;/p&gt;
