@article{Li_Ye_Zhang_Zhang_2023, title={Reviewing Labels: Label Graph Network with Top-k Prediction Set for Relation Extraction}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26533}, DOI={10.1609/aaai.v37i11.26533}, abstractNote={The typical way for relation extraction is fine-tuning large pre-trained language models on task-specific datasets, then selecting the label with the highest probability of the output
distribution as the final prediction. However, the usage of the Top-k prediction set for a given sample is commonly overlooked. In this paper, we first reveal that the Top-k prediction
set of a given sample contains useful information for predicting the correct label. To effectively utilizes the Top-k prediction set, we propose Label Graph Network with Top-k Prediction Set, termed as KLG. Specifically, for a given sample, we build a label graph to review candidate labels in the Top-k prediction set and learn the connections between them. We also design a dynamic k selection mechanism to learn more powerful and discriminative relation representation. Our experiments show that KLG achieves the best performances on three relation extraction datasets. Moreover, we observe thatKLG is more effective in dealing with long-tailed classes.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Bo and Ye, Wei and Zhang, Jinglei and Zhang, Shikun}, year={2023}, month={Jun.}, pages={13051-13058} }

@article{Shimizu_Higa_Takahashi_Fujita_Nakadai_2024, title={Scalable Negotiating Agent Strategy via Multi-Issue Policy Network (Student Abstract)}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/27023}, DOI={10.1609/aaai.v37i13.27023}, abstractNote={Previous research on the comprehensive negotiation strategy using deep reinforcement learning (RL) has scalability issues of not performing effectively in the large-sized domains.
We improve negotiation strategy via deep RL by considering an issue-based represented deep policy network to deal with multi-issue negotiation.
The architecture of the proposed learning agent considers the characteristics of multi-issue negotiation domains and policy-based learning.
We demonstrate that proposed method achieve equivalent or higher utility than existing negotiation agents in the large-sized domains.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shimizu, Takumu and Higa, Ryota and Takahashi, Toki and Fujita, Katsuhide and Nakadai, Shinji}, year={2024}, month={Jul.}, pages={16326-16327} }

@article{So_E. Ali_Güler_Jiao_Avestimehr_2023, title={Securing Secure Aggregation: Mitigating Multi-Round Privacy Leakage in Federated Learning}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26177}, DOI={10.1609/aaai.v37i8.26177}, abstractNote={Secure aggregation is a critical component in federated learning (FL), which enables the server to learn the aggregate model of the users without observing their local models. Conventionally, secure aggregation algorithms focus only on ensuring the privacy of individual users in a single training round. We contend that such designs can lead to significant privacy leakages over multiple training rounds, due to partial user selection/participation at each round of FL. In fact, we show that the conventional random user selection strategies in FL lead to leaking users’ individual models within number of rounds that is linear in the number of users.
To address this challenge, we introduce a secure aggregation framework, Multi-RoundSecAgg, with multi-round privacy guarantees.
In particular, we introduce a new metric to quantify the privacy guarantees of FL over multiple training rounds, and develop a structured user selection strategy that guarantees the long-term privacy of each user (over any number of training rounds). Our framework also carefully accounts for the fairness and the average number of participating users at each round.
Our experiments on MNIST, CIFAR-10 and CIFAR-100 datasets in the IID and the non-IID settings demonstrate the performance improvement over the baselines, both in terms of privacy protection and test accuracy.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={So, Jinhyun and E. Ali, Ramy and Güler, Başak and Jiao, Jiantao and Avestimehr, A. Salman}, year={2023}, month={Jun.}, pages={9864-9873} }

@article{Liu_Bao_Zhao_Huang_2023, title={Selective Knowledge Distillation for Non-Autoregressive Neural Machine Translation}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26555}, DOI={10.1609/aaai.v37i11.26555}, abstractNote={Benefiting from the sequence-level knowledge distillation, the Non-Autoregressive Transformer (NAT) achieves great success in neural machine translation tasks. However, existing knowledge distillation has side effects, such as propagating errors from the teacher to NAT students, which may limit further improvements of NAT models and are rarely discussed in existing research.
In this paper, we introduce selective knowledge distillation by introducing an NAT evaluator to select NAT-friendly targets that are of high quality and easy to learn.
In addition, we introduce a simple yet effective progressive distillation method to boost NAT performance. Experiment results on multiple WMT language directions and several representative NAT models show that our approach can realize a flexible trade-off between the quality and complexity of training data for NAT models, achieving strong performances.
Further analysis shows that distilling only 5% of the raw translations can help an NAT outperform its counterpart trained on raw data by about 2.4 BLEU.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Min and Bao, Yu and Zhao, Chengqi and Huang, Shujian}, year={2023}, month={Jun.}, pages={13246-13254} }

@article{Dai_Li_Cheng_2023, title={Semi-Supervised Deep Regression with Uncertainty Consistency and Variational Model Ensembling via Bayesian Neural Networks}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25890}, DOI={10.1609/aaai.v37i6.25890}, abstractNote={Deep regression is an important problem with numerous applications. These range from computer vision tasks such as age estimation from photographs, to medical tasks such as ejection fraction estimation from echocardiograms for disease tracking.
Semi-supervised approaches for deep regression are notably under-explored compared to classification and segmentation tasks, however. Unlike classification tasks, which rely on thresholding functions for generating class pseudo-labels, regression tasks use real number target predictions directly as pseudo-labels, making them more sensitive to prediction quality.
In this work, we propose a novel approach to semi-supervised regression, namely Uncertainty-Consistent Variational Model Ensembling (UCVME), which improves training by generating high-quality pseudo-labels and uncertainty estimates for heteroscedastic regression.
Given that aleatoric uncertainty is only dependent on input data by definition and should be equal for the same inputs, we present a novel uncertainty consistency loss for co-trained models.
Our consistency loss significantly improves uncertainty estimates and allows higher quality pseudo-labels to be assigned greater importance under heteroscedastic regression. Furthermore, we introduce a novel variational model ensembling approach to reduce prediction noise and generate more robust pseudo-labels. We analytically show our method generates higher quality targets for unlabeled data and further improves training. Experiments show that our method outperforms state-of-the-art alternatives on different tasks and can be competitive with supervised methods that use full labels. Code is available at https://github.com/xmed-lab/UCVME.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Dai, Weihang and Li, Xiaomeng and Cheng, Kwang-Ting}, year={2023}, month={Jun.}, pages={7304-7313} }

@article{Krogmann_Lenzner_Skopalik_2023, title={Strategic Facility Location with Clients That Minimize Total Waiting Time}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25709}, DOI={10.1609/aaai.v37i5.25709}, abstractNote={We study a non-cooperative two-sided facility location game in which facilities and clients behave strategically.
This is in contrast to many other facility location games in which clients simply visit their closest facility.
Facility agents select a location on a graph to open a facility to attract as much purchasing power as possible, while client agents choose which facilities to patronize by strategically distributing their purchasing power in order to minimize their total waiting time. Here, the waiting time of a facility depends on its received total purchasing power. We show that our client stage is an atomic splittable congestion game, which implies existence, uniqueness and efficient computation of a client equilibrium.
Therefore, facility agents can efficiently predict client behavior and make strategic decisions accordingly.
Despite that, we prove that subgame perfect equilibria do not exist in all instances of this game and that their existence is NP-hard to decide.
On the positive side, we provide a simple and efficient algorithm to compute 3-approximate subgame perfect equilibria.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Krogmann, Simon and Lenzner, Pascal and Skopalik, Alexander}, year={2023}, month={Jun.}, pages={5714-5721} }

@article{Wang_Zhang_Valkanas_Tang_Ma_Hao_Coates_2023, title={Structure Aware Incremental Learning with Personalized Imitation Weights for Recommender Systems}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25595}, DOI={10.1609/aaai.v37i4.25595}, abstractNote={Recommender systems now consume large-scale data and play a significant role in improving user experience. Graph Neural Networks (GNNs) have emerged as one of the most effective recommender system models because they model the rich relational information. The ever-growing volume of data can make training GNNs prohibitively expensive. To address this, previous attempts propose to train the GNN models incrementally as new data blocks arrive. Feature and structure knowledge distillation techniques have been explored to allow the GNN model to train in a fast incremental fashion while alleviating the catastrophic forgetting problem. However, preserving the same amount of the historical information for all users is sub-optimal since it fails to take into account the dynamics of each user’s change of preferences. For the users whose interests shift substantially, retaining too much of the old knowledge can overly constrain the model, preventing it from quickly adapting to the users’ novel interests. In contrast, for users who have static preferences, model performance can benefit greatly from preserving as much of the user’s long-term preferences as possible.
In this work, we propose a novel training strategy that adaptively learns personalized imitation weights for each user to balance the contribution from the recent data and the amount of knowledge to be distilled from previous time periods.
We demonstrate the effectiveness of learning imitation weights via a comparison on five diverse datasets for three state-of-art structure distillation based recommender systems. The performance shows consistent improvement over competitive incremental learning techniques.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Yuening and Zhang, Yingxue and Valkanas, Antonios and Tang, Ruiming and Ma, Chen and Hao, Jianye and Coates, Mark}, year={2023}, month={Jun.}, pages={4711-4719} }

@article{Abroshan_Mishra_Khalili_2023, title={Symbolic Metamodels for Interpreting Black-Boxes Using Primitive Functions}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25816}, DOI={10.1609/aaai.v37i6.25816}, abstractNote={One approach for interpreting black-box machine learning models is to find a global approximation of the model using simple interpretable functions, which is called a metamodel (a model of the model). Approximating the black-box with
a metamodel can be used to 1) estimate instance-wise feature importance; 2) understand the functional form of the model; 3) analyze feature interactions. In this work, we propose a new method for finding interpretable metamodels. Our approach utilizes Kolmogorov superposition theorem, which expresses multivariate functions as a composition of univariate functions (our primitive parameterized
functions). This composition can be represented in the form of a tree. Inspired by symbolic regression, we use a modified form of genetic programming to search over different tree configurations. Gradient descent (GD) is used to optimize the parameters of a given configuration. Our method is a novel memetic algorithm that uses GD not only for training numerical constants but also for the training
of building blocks. Using several experiments, we show that our method outperforms recent metamodeling approaches suggested for interpreting black-boxes.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Abroshan, Mahed and Mishra, Saumitra and Khalili, Mohammad Mahdi}, year={2023}, month={Jun.}, pages={6649-6657} }

@article{Wang_Fan_Kankanhalli_2023, title={Text to Point Cloud Localization with Relation-Enhanced Transformer}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25347}, DOI={10.1609/aaai.v37i2.25347}, abstractNote={Automatically localizing a position based on a few natural language instructions is essential for future robots to communicate and collaborate with humans. To approach this goal, we focus on a text-to-point-cloud cross-modal localization
problem. Given a textual query, it aims to identify the described location from city-scale point clouds. The task involves two challenges. 1) In city-scale point clouds, similar ambient instances may exist in several locations. Searching each location in a huge point cloud with only instances as guidance may lead to less discriminative signals and incorrect results. 2) In textual descriptions, the hints are provided separately. In this case, the relations among those hints are not
explicitly described, leaving the difficulties of learning relations to the agent itself. To alleviate the two challenges, we propose a unified Relation-Enhanced Transformer (RET) to improve representation discriminability for both point cloud
and nature language queries. The core of the proposed RET is a novel Relation-enhanced Self-Attention (RSA) mechanism, which explicitly encodes instance (hint)-wise relations for the two modalities. Moreover, we propose a fine-grained cross-modal matching method to further refine the location predictions in a subsequent instance-hint matching stage. Experimental results on the KITTI360Pose dataset demonstrate that our approach surpasses the previous state-of-the-art method by large margins.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Guangzhi and Fan, Hehe and Kankanhalli, Mohan}, year={2023}, month={Jun.}, pages={2501-2509} }

@article{Bachor_Bergdoll_Nebel_2023, title={The Multi-Agent Transportation Problem}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26362}, DOI={10.1609/aaai.v37i10.26362}, abstractNote={We introduce the multi-agent transportation (MAT) problem, where agents have to transport containers from their starting positions to their designated goal positions. Movement takes place in a common environment where collisions between agents and between containers must be avoided.
In contrast to other frameworks such as multi-agent pathfinding (MAPF) or multi-agent pickup and delivery (MAPD), the agents are allowed to separate from the containers at any time, which can reduce the makespan and also allows for plans in scenarios that are unsolvable otherwise.
We present a complexity analysis establishing the problem’s NP-completeness and show how the problem can be reduced to a sequence of SAT problems when optimizing for makespan.
A MAT solver is empirically evaluated with regard to varying input characteristics and movement constraints and compared to a MAPD solver that utilizes conflict-based search (CBS).}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bachor, Pascal and Bergdoll, Rolf-David and Nebel, Bernhard}, year={2023}, month={Jun.}, pages={11525-11532} }

@article{Meinert_Gawlikowski_Lavin_2023, title={The Unreasonable Effectiveness of Deep Evidential Regression}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26096}, DOI={10.1609/aaai.v37i8.26096}, abstractNote={There is a significant need for principled uncertainty reasoning in machine learning systems as they are increasingly deployed in safety-critical domains.
A new approach with uncertainty-aware regression-based neural networks (NNs), based on learning evidential distributions for aleatoric and epistemic uncertainties, shows promise over traditional deterministic methods and typical Bayesian NNs, notably with the capabilities to disentangle aleatoric and epistemic uncertainties.
Despite some empirical success of Deep Evidential Regression (DER), there are important gaps in the mathematical foundation that raise the question of why the proposed technique seemingly works.
We detail the theoretical shortcomings and analyze the performance on synthetic and real-world data sets, showing that Deep Evidential Regression is a heuristic rather than an exact uncertainty quantification.
We go on to discuss corrections and redefinitions of how aleatoric and epistemic uncertainties should be extracted from NNs.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Meinert, Nis and Gawlikowski, Jakob and Lavin, Alexander}, year={2023}, month={Jun.}, pages={9134-9142} }

