@article{Iida_Sonobe_Inaba_2024, title={Understand Restart of SAT Solver Using Search Similarity Index (Student Abstract)}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26978}, DOI={10.1609/aaai.v37i13.26978}, abstractNote={SAT solvers are widely used to solve many industrial problems because of their high performance, which is achieved by various heuristic methods.
Understanding why these methods are effective is essential to improving them. One approach to this is analyzing them using qualitative measurements.
In our previous study, we proposed search similarity index (SSI), a metric to quantify the similarity between searches. SSI significantly improved the performance of the parallel SAT solver.
Here, we apply SSI to analyze the effect of restart, a key SAT solver technique.
Experiments using SSI reveal the correlation between the difficulty of instances and the search change effect by restart, and the reason behind the effectiveness of the state-of-the-art restart method is also explained.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Iida, Yoichiro and Sonobe, Tomohiro and Inaba, Mary}, year={2024}, month={Jul.}, pages={16236-16237} }

@article{Lou_Lu_Dai_Jia_Lin_Han_Sun_Wu_2023, title={Universal Information Extraction as Unified Semantic Matching}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26563}, DOI={10.1609/aaai.v37i11.26563}, abstractNote={The challenge of information extraction (IE) lies in the diversity of label schemas and the heterogeneity of structures.
Traditional methods require task-specific model design and rely heavily on expensive supervision, making them difficult to generalize to new schemas.
In this paper, we decouple IE into two basic abilities, structuring and conceptualizing, which are shared by different tasks and schemas.
Based on this paradigm, we propose to universally model various IE tasks with Unified Semantic Matching (USM) framework, which introduces three unified token linking operations to model the abilities of structuring and conceptualizing.
In this way, USM can jointly encode schema and input text, uniformly extract substructures in parallel, and controllably decode target structures on demand.
Empirical evaluation on 4 IE tasks shows that the proposed method achieves state-of-the-art performance under the supervised experiments and shows strong generalization ability in zero/few-shot transfer settings.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lou, Jie and Lu, Yaojie and Dai, Dai and Jia, Wei and Lin, Hongyu and Han, Xianpei and Sun, Le and Wu, Hua}, year={2023}, month={Jun.}, pages={13318-13326} }

@article{Ran_Jia_2023, title={Unsupervised Cross-Domain Rumor Detection with Contrastive Learning and Cross-Attention}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26584}, DOI={10.1609/aaai.v37i11.26584}, abstractNote={Massive rumors usually appear along with breaking news or trending topics, seriously hindering the truth. Existing rumor detection methods are mostly focused on the same domain, thus have poor performance in cross-domain scenarios due to domain shift. In this work, we propose an end-to-end instance-wise and prototype-wise contrastive learning model with cross-attention mechanism for cross-domain rumor detection. The model not only performs cross-domain
feature alignment, but also enforces target samples to align with the corresponding prototypes of a given source domain. Since target labels in a target domain are unavailable, we use a clustering-based approach with carefully initialized centers
by a batch of source domain samples to produce pseudo labels. Moreover, we use a cross-attention mechanism on a pair of source data and target data with the same labels to learn domain-invariant representations. Because the samples in a
domain pair tend to express similar semantic patterns especially on the people’s attitudes (e.g., supporting or denying) towards the same category of rumors, the discrepancy between a pair of source domain and target domain will be decreased. We conduct experiments on four groups of cross-domain datasets and show that our proposed model achieves state-of-the-art performance.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ran, Hongyan and Jia, Caiyan}, year={2023}, month={Jun.}, pages={13510-13518} }

@article{Liu_Sun_Wu_Xu_Han_Li_Gong_2023, title={Unsupervised Paraphrasing under Syntax Knowledge}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/26558}, DOI={10.1609/aaai.v37i11.26558}, abstractNote={The soundness of syntax is an important issue for the paraphrase generation task. Most methods control the syntax of paraphrases by embedding the syntax and semantics in the generation process, which cannot guarantee the syntactical correctness of the results. Different from them, in this paper we investigate the structural patterns of word usages termed as the word composable knowledge and integrate it into the paraphrase generation to control the syntax in an explicit way.
This syntax knowledge is pretrained on a large corpus with the dependency relationships and formed as the probabilistic functions on the word-level syntactical soundness.
For the sentence-level correctness, we design a hierarchical syntax structure loss to quantitatively verify the syntactical soundness of the paraphrase against the given dependency template. Thus, the generation process can select the appropriate words with consideration on both semantics and syntax. The proposed method is evaluated on a few paraphrase datasets.
The experimental results show that the quality of paraphrases by our proposed method outperforms the compared methods, especially in terms of syntax correctness.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Tianyuan and Sun, Yuqing and Wu, Jiaqi and Xu, Xi and Han, Yuchen and Li, Cheng and Gong, Bin}, year={2023}, month={Jun.}, pages={13273-13281} }

@article{Bitton_Yosef_Strugo_Shahaf_Schwartz_Stanovsky_2023, title={VASR: Visual Analogies of Situation Recognition}, volume={37}, url={https://ojs.aaai.org/index.php/AAAI/article/view/25096}, DOI={10.1609/aaai.v37i1.25096}, abstractNote={A core process in human cognition is analogical mapping: the ability to identify a similar relational structure between different situations.
We introduce a novel task, Visual Analogies of Situation Recognition, adapting the classical word-analogy task into the visual domain. Given a triplet of images, the task is to select an image candidate B’ that completes the analogy (A to A’ is like B to what?). Unlike previous work on visual analogy that focused on simple image transformations, we tackle complex analogies requiring understanding of scenes. We leverage situation recognition annotations and the CLIP model to generate a large set of 500k candidate analogies. Crowdsourced annotations for a sample of the data indicate that humans agree with the dataset label ~80% of the time (chance level 25%). Furthermore, we use human annotations to create a gold-standard dataset of 3,820 validated analogies.
Our experiments demonstrate that state-of-the-art models do well when distractors are chosen randomly (~86%), but struggle with carefully chosen distractors (~53%, compared to 90% human accuracy). We hope our dataset will encourage the development of new analogy-making models. Website: https://vasr-dataset.github.io/}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bitton, Yonatan and Yosef, Ron and Strugo, Eliyahu and Shahaf, Dafna and Schwartz, Roy and Stanovsky, Gabriel}, year={2023}, month={Jun.}, pages={241-249} }
